  "stats.about.walls": "Osoba i njezini preci čiji otac ili majka nisu u datoteci, od najbližih nadalje. Broj je generacija u kojoj nedostaje roditelj, kao na grafu Preci po generacijama (1 su roditelji, 2 djedovi i bake …). Kod svakoga od njih loza završava, pa je na vrhu popisa ono gdje se istraživanje najprije može nastaviti. Klik na ime otvara osobu u Uređivanju.",
