  "stats.click.network": "Kad mišem zastanete na prezimenu, istaknu se njegova vjenčanja. Klikom na prezime ili liniju prikazuje se popis tih vjenčanja; svako možete otvoriti u Uređivanju.",
  "stats.click.marriages": "Klikom na par prikazuje se popis njegovih vjenčanja; svako možete otvoriti u Uređivanju.",
  "stats.about.surnameNetwork": "Prezimena s najviše vjenčanja s drugim prezimenima. Linija spaja dva prezimena kad su se njihovi nositelji međusobno vjenčali barem dvaput. Veći krug znači više osoba s tim prezimenom, a deblja linija više vjenčanja. Vjenčanje se broji ako oba supružnika imaju prezime; žena se broji pod prezimenom iz svojega imena, obično je to djevojačko prezime.",
  "stats.about.surnamePairs": "Parovi različitih prezimena, poredani po broju vjenčanja između njihovih nositelja. Vjenčanje se broji ako oba supružnika imaju prezime. Zapisi koji se razlikuju samo po dijakritičkim znakovima ili velikim slovima broje se kao jedan.",
  "stats.about.complete": "Udio osoba u odabiru koje imaju pojedini podatak. Ime i prezime broje se ako su upisana oba i nijedno nije zamjena poput NN. Krštenje se računa kao datum i mjesto rođenja, a pokop ili kremacija kao datum smrti; redak s datumom smrti uzima u obzir samo preminule. Redak „Bilo koje mjesto“ broji mjesto kod bilo kojeg događaja osobe, a redak „Na karti“ samo ako to mjesto igdje u datoteci ima koordinate. Navod izvora broji se ako je upisan kod osobe ili kod bilo kojeg njezina događaja.",
  "stats.about.surnames": "Prezimena, kod svake osobe brojena jednom. Zapisi koji se razlikuju samo po dijakritičkim znakovima ili velikim slovima broje se kao jedan; prikazan je zapis koji je u datoteci najčešći.",
