  "stats.about.byCentury": "Pet najčešćih prvih imena među muškarcima i među ženama rođenima u pojedinom stoljeću.",
  "stats.about.occupationsPerPerson": "Koliko različitih zanimanja ima pojedina osoba s barem jednim upisanim zanimanjem. Zapis s više zanimanja (½ zemljak, gostač) broji svako posebno; isto zanimanje upisano dvaput broji se jednom.",
  "stats.about.givenCount": "Koliko imena ima pojedina osoba.",
  "stats.about.nameKinds": "Koliko osoba ima pojedinu vrstu dodatnog imena (prezime u braku, poznat kao, nadimak …); svaka se vrsta kod osobe broji jednom. Zadnja dva retka broje osobe čije glavno ime nema imena ili prezimena: polje je prazno ili sadrži zamjenu poput NN.",
  "stats.about.namesakes": "Udio sinova i kćeri koji imaju isto prvo ime kao otac, majka, djed ili baka. Svaki redak broji samo djecu kod koje je ime tog srodnika poznato.",
  "stats.about.ageAtDeath": "Navršene godine od rođenja (ili krštenja) do smrti (ili pokopa), u petogodišnjim skupinama. Broje se samo osobe s oba datuma; približni datumi (ABT, BEF, AFT, BET) broje se samo ako je uključeno „Broji približne datume“.",
  "stats.about.lifeByCentury": "Prosječna dob pri smrti osoba rođenih u pojedinoj četvrtini stoljeća (kod datoteka koje sežu daleko u prošlost, u polovici stoljeća ili stoljeću). Smrti dojenčadi znatno je snižavaju; dijagram za one koji su doživjeli 5 godina izostavlja ih. Razdoblje s manje od 5 umrlih je izostavljeno. Izostavljeno je i razdoblje u kojem je još živo više od četvrtine rođenih, jer su među umrlima iz njega uglavnom oni koji su umrli mladi.",
  "stats.about.lifeAdults": "Isti prosjek, ali samo za osobe koje su doživjele 5 godina. Bolje pokazuje koliko je godina obično doživio odrastao čovjek.",
  "stats.about.childSurvival": "Za obitelji s djecom iz pojedine četvrtine stoljeća (prema datumu vjenčanja, inače prema rođenju prvog djeteta): koliko je djece po obitelji doživjelo 18 godina (zeleni donji dio stupca) i koliko ih je umrlo prije (crveni gornji dio). Kad je stupaca malo, iznad svakoga je ispisan udio djece koja su doživjela 18 godina. Svi brojevi stupca prikazuju se kad mišem zastanete na njemu. Dijete bez datuma smrti računa se kao odraslo ako se vjenčalo ili je živo i starije od 18 godina; inače se ne broji. Kad datoteka rijetko bilježi smrti, broj odrasle djece zato ispada prenizak. Razdoblje s manje od 5 obitelji je izostavljeno, kao i posljednje razdoblje jer sva djeca iz njega još nisu odrasla.",
  "stats.about.childDeaths": "Među osobama rođenima u pojedinoj četvrtini stoljeća čija je dob pri smrti poznata, udio onih koje su umrle prije 5. godine života. Izostavljena su ista razdoblja kao kod prosječne dobi pri smrti.",
  "stats.about.oldest": "Deset najviših dobi pri smrti u odabiru.",
  "stats.about.marriageMen": "Dob svakog muškarca pri njegovu prvom vjenčanju s datumom, u petogodišnjim skupinama. Vjenčanja bez datuma i muškarci bez datuma rođenja nisu uzeti u obzir.",
  "stats.about.marriageWomen": "Dob svake žene pri njezinu prvom vjenčanju s datumom, u petogodišnjim skupinama. Vjenčanja bez datuma i žene bez datuma rođenja nisu uzete u obzir.",
  "stats.about.ageGap": "Muževa dob pri vjenčanju umanjena za ženinu. Negativna vrijednost znači da je starija bila žena.",
  "stats.about.marriageMonth": "Vjenčanja po mjesecu u datumu; datumi bez mjeseca nisu uzeti u obzir. U crkvenim knjigama česte su praznine u došašću i korizmi, kad se vjenčanja nisu sklapala.",
  "stats.about.children": "Broj djece upisane u pojedinoj obitelji u odabiru, zajedno s obiteljima bez djece.",
  "stats.about.childrenByCentury": "Prosječan broj djece u obitelji po četvrtini stoljeća vjenčanja — ili po četvrtini stoljeća rođenja prvog djeteta, ako vjenčanje nema datum. Razdoblje s manje od 5 obitelji je izostavljeno, kao i posljednje razdoblje jer se obitelji iz njega možda još povećavaju.",
  "stats.about.firstChild": "Mjeseci od vjenčanja do rođenja prvog djeteta, gdje oba datuma navode mjesec. Dijete rođeno unutar osam mjeseci nakon vjenčanja možda je začeto prije njega.",
