  "stats.about.marriageDecade": "Vjenčanja po godini vjenčanja, u desetljećima — ili u duljim razdobljima ako datoteka obuhvaća više stoljeća. Prva vjenčanja su u donjem dijelu stupca, ponovna u gornjem: ponovno je vjenčanje ono pri kojem je mladoženja ili mladenka već prije sklopio brak, prema ranijem vjenčanju s datumom.",
  "stats.about.birthDecade": "Rođenja (ili krštenja) po godinama, u desetljećima — ili u duljim razdobljima ako datoteka obuhvaća više stoljeća. Muškarci su u donjem dijelu stupca, žene u gornjem; broj iznad stupca obuhvaća sve, i osobe nepoznatog spola.",
