  "tools.validate.fixConformCoverageHint": "GEDCOM 5.5.1 i 7.0 navode što izvor obuhvaća u bloku DATA > EVEN: vrstu događaja koju izvor bilježi, a ispod nje mjesto i razdoblje. Vrsta događaja očitava se iz naslova izvora (matična knjiga krštenih, vjenčanih ili umrlih). Izvor čiji naslov to ne kaže ostaje nepromijenjen jer standard za EVEN zahtijeva vrstu događaja. Ispod DATA premješta se i ustanova izvora.",
