  "tools.batch.previewSkip": "bit će preskočeno",
  "tools.batch.previewSkipEstimate": "procjena nije moguća — preskočeno",
  "tools.batch.estimateBirthHint": "Kad događaj s datumom navodi dob osobe (smrt u dobi od 62 godine), iz te se dobi izračunava godina rođenja i zapisuje kao „CAL godina“. Inače se zapisuje datum rođenja „ABT godina“, procijenjen iz godina rođenja roditelja, supružnika, djece ili braće i sestara te uvijek zaokružen na godinu koja završava na 0 ili 5, kako bi se procjene razlikovale od zabilježenih datuma. Kad netko od braće i sestara ima datum rođenja, procjena ostalih oslanja se na njega prema redoslijedu djece u obitelji. Osobe koje već imaju datum rođenja ili krštenja i osobe bez bliskog srodnika s datumom preskaču se — ponovnim pokretanjem mogu se dosegnuti preko novozapisanih procjena.",
  "tools.batch.action.estimateMarriage": "Dodaj procijenjeni datum vjenčanja",
  "tools.batch.estimateMarriageHint": "Svako zabilježeno vjenčanje bez datuma dobiva najbolju procjenu koju obitelj omogućuje; zajednica bez zabilježenog vjenčanja ne dobiva je. Ako netko od djece ima zabilježen datum rođenja, zapisuje se datum „prije“ rođenja najstarijeg djeteta, zajedno s danom i mjesecom — par se vjenčava prije rođenja prvog djeteta. Inače se zapisuje datum „oko“ godine: dvije godine prije procijenjenog rođenja najstarijeg djeteta ili, kad nema djeteta s datumom, iz godina rođenja supružnika (žena se udaje s otprilike 25 godina, muž se ženi s otprilike 30). Godina procjene „oko“ uvijek završava na 0 ili 5. Na isti se način ispravlja procjena „prije“ koja je kasnija od rođenja najstarijeg djeteta i procjena „oko“ prije koje se najstarije dijete već rodilo. U obzir se uzimaju samo djeca rođena paru, a ne posvojena ni udomljena. Ostali datumi, obitelji sa samo jednim roditeljem (najčešće je riječ o izvanbračnom djetetu) i obitelji bez datuma iz kojeg bi se mogla izvesti procjena preskaču se.",
  "tools.batch.action.addMarriedName": "Dodaj bračno prezime po partneru",
  "tools.batch.addMarriedNameHint": "Prezime svakog partnera zapisuje kao bračno prezime osobe, i to onako kako bračna prezimena zapisuje ova datoteka. Doprinosi svaka zajednica, redom od prvog vjenčanja nadalje, pa drugo vjenčanje dodaje drugo prezime; prezimena koja osoba već ima ne mijenjaju se. Osobe čiji partner nema vlastito prezime preskaču se. Osobe čija zajednica nema zabilježeno vjenčanje na početku su neoznačene — ako ih označite, prezime se ipak zapisuje.",
