  "tools.geocode.addr.applied_few": "Upisano u {{count}} zapisa.",
  "tools.geocode.addr.applied_other": "Upisano u {{count}} zapisa.",
  "tools.geocode.addr.move": "Premjesti u drugo mjesto…",
  "tools.geocode.addr.moveHint": "Premješta samo ove adrese u drugo mjesto — za zaselak koji datoteka vodi pod susjednim naseljem.",
  "tools.geocode.addr.moveIntro": "Označene adrese dobivaju novo mjesto; retci adrese ostaju nepromijenjeni, a koordinata postaje ona koju datoteka vodi za novo mjesto — ako je datoteka nema, ostaje nepromijenjena.",
  "tools.geocode.addr.movePlaceholder": "Novo mjesto, npr. Klošter, Metlika, Slovenija",
  "tools.geocode.addr.moveCount_one": "{{count}} adresa · događaja: {{events}}",
