  "tools.geocode.addr.moveApply": "Premjesti ({{count}})",
  "tools.geocode.addr.moved_one": "Premješteno — ažuriran {{count}} zapis.",
  "tools.geocode.addr.moved_few": "Premješteno — ažurirana {{count}} zapisa.",
  "tools.geocode.addr.moved_other": "Premješteno — ažurirano {{count}} zapisa.",
  "tools.geocode.addr.bulk": "Više adresa na jednu koordinatu…",
  "tools.geocode.addr.bulkHint": "Označenim adresama dodjeljuje isti približni položaj — za adrese koje registar ne poznaje: staro numeriranje, imanje kojeg više nema.",
  "tools.geocode.addr.bulkIntro": "Odaberite jedan položaj — dovoljno je središte sela — i preuzimaju ga sve označene adrese. Namjerno je približan: događaje stavlja na kartu ondje gdje registar ne može smjestiti zgradu. Odabiri su pripremljeni, potvrdite ih gumbom Upiši koordinate gore.",
  "tools.geocode.addr.bulkNoCoord": "položaj još nije odabran",
  "tools.geocode.addr.bulkPrefixLabel": "Počinje s",
  "tools.geocode.addr.bulkPrefix": "Npr. Stražišče 11",
  "tools.geocode.addr.bulkPrefixHint": "Označava samo adrese koje počinju ovim tekstom — oba imanja istog kućnog broja ili niz numeriranja. Prazno označava cijelo mjesto.",
  "tools.geocode.addr.bulkApply_one": "Primijeni na {{count}} adresu",
