  "tools.geocode.addr.splitFound_one": "{{count}} adresa (događaja: {{events}}) prema registru je u naselju {{settlement}}, a ne u mjestu {{place}}.",
  "tools.geocode.addr.splitFound_few": "{{count}} adrese (događaja: {{events}}) prema registru su u naselju {{settlement}}, a ne u mjestu {{place}}.",
