  "tools.geocode.addr.splitMove": "Premjesti ih u mjesto {{place}}",
  "tools.geocode.fromFile": "iz ove datoteke",
  "tools.geocode.fromFileTooltip": "Druga navođenja točno ovog naziva mjesta u datoteci već nose ovu koordinatu",
  "tools.geocode.countryTooltip": "Država čija se mjesta preuzimaju iz OpenStreetMapa (Overpass API, © suradnici OpenStreetMapa)",
  "tools.geocode.serviceFailed": "Preuzimanje nije uspjelo jer se poslužitelj izvora nije odazvao ili je vratio pogrešku. Pokušajte ponovno malo kasnije.",
  "tools.geocode.downloadFailed": "Preuzimanje nije uspjelo — pokušajte za minutu (poslužitelji Overpass ograničavaju broj zahtjeva) ili preuzmite datoteku GeoNames sa stranice u nastavku i uvezite je ovdje.",
  "tools.geocode.emptyResult": "Preuzimanje je uspjelo, ali u preuzetom nije bilo ničega za uvoz. Možda kod izvora trenutačno nešto ne valja — pokušajte kasnije ili ovu državu preuzmite iz nekog drugog izvora u nastavku.",
  "tools.geocode.unreadable": "Preuzimanje nije sadržavalo ono što ovaj izvor šalje ({{detail}}) — pokušajte kasnije ili ovu državu preuzmite iz nekog drugog izvora u nastavku.",
  "tools.geocode.stalled": "Uvoz se zaustavio a da nije završio i nije rekao zašto — najčešće je pregledniku ponestalo memorije. Ništa nije spremljeno; pokušajte ponovno.",
  "tools.geocode.storeBlocked": "Preuzimanje je uspjelo, ali preglednik nije pohranio preuzete podatke: baza podataka o mjestima otvorena je u drugom prozoru aplikacije. Zatvorite ostale kartice i prozore aplikacije, a zatim ponovite preuzimanje.",
  "tools.geocode.storeRefused": "Preuzimanje je uspjelo, ali preglednik nije pohranio preuzete podatke ({{detail}}). Najčešće je disk pun ili je preglednik postavljen tako da za ovo web-mjesto ne čuva podatke.",
  "tools.geocode.regionsLoading": "Previše za jedno preuzimanje — upit po regijama",
  "tools.geocode.tooLargeNoRegions": "Ova država ima više mjesta nego što ih poslužitelj OpenStreetMapa šalje odjednom, a nema regija po kojima bi se mogla preuzeti u dijelovima. Sa stranice u nastavku preuzmite datoteku GeoNames za nju i uvezite nju.",
  "tools.geocode.regionIntro": "{{country}} ima više mjesta nego što ih OpenStreetMap šalje odjednom, pa se preuzima po regijama — ima ih {{count}}. Svaka se pridružuje istom imeniku mjesta, pa odaberite regije u kojima istražujete ili jednostavno sve.",
  "tools.geocode.regionPick": "Jedna regija…",
  "tools.geocode.regionAll": "Sve regije ({{count}})",
  "tools.geocode.regionAllHint": "Regije se preuzimaju jedna za drugom, svaka otprilike minutu, i svaka se odmah sprema — možete zaustaviti u bilo kojem trenutku. Za cijelu državu odjednom datoteka GeoNames jedno je preuzimanje.",
  "tools.geocode.regionDismiss": "Ne sada",
  "tools.geocode.regionProgress": "{{name}} ({{index}}/{{total}})",
  "tools.geocode.regionTooLarge": "I regija {{region}} prevelika je za jedno preuzimanje — pokušajte ponovno kad poslužitelj bude manje opterećen ili upotrijebite datoteku GeoNames.",
  "tools.geocode.regionAllFailed_one": "Preuzimanje nije uspjelo za {{count}} regiju: {{names}}. Preuzmite je zasebno kad poslužitelj bude manje opterećen.",
  "tools.geocode.regionAllFailed_few": "Preuzimanje nije uspjelo za {{count}} regije: {{names}}. Preuzmite ih zasebno kad poslužitelj bude manje opterećen.",
  "tools.geocode.regionAllFailed_other": "Preuzimanje nije uspjelo za {{count}} regija: {{names}}. Preuzmite ih zasebno kad poslužitelj bude manje opterećen.",
  "tools.geocode.sourceGurs": "Sva slovenska naselja iz službenog registra prostornih jedinica, zajedno s dvojezičnim nazivima, i svaki kućni broj u državi s vlastitom koordinatom — za Sloveniju najpouzdaniji izbor.",
  "tools.geocode.licenseCcBy": ", licenca CC BY 4.0.",
  "tools.geocode.sourceDgu": "Hrvatska naselja, sela, zaseoci i gradske četvrti iz službenog registra geografskih imena, zajedno s povijesnim i dvojezičnim oblicima, i svaki kućni broj u državi s vlastitom koordinatom — za Hrvatsku najpouzdaniji izbor.",
  "tools.geocode.licenseOpen": ", licenca Open Licence.",
  "tools.geocode.sourceOsm": "Bilo koja država s popisa. I zaseoci koje službeni registar ne imenuje.",
  "tools.geocode.sourceOsmCredit": "© suradnici",
  "tools.geocode.sourceOsmLicense": ", licenca ODbL.",
  "tools.geocode.storedLocally": "Što god učitate, ostaje u ovom pregledniku; nikamo se ne šalje. Imenici mjesta međusobno se nadopunjuju, a ne zamjenjuju: isto naselje iz dvaju imenika među prijedlozima je jednom, sa službenom koordinatom, a dva različita mjesta istog naziva ostaju odvojena i birate između njih.",
  "tools.geocode.gursName": "GURS (Slovenija)",
  "tools.geocode.dguName": "DGU (Hrvatska)",
  "tools.geocode.sourcePlaces": "Mjesta",
  "tools.geocode.sourceAddresses": "Adrese",
  "tools.geocode.gursTooltip": "Svih 6035 slovenskih naselja iz registra prostornih jedinica (Geodetska uprava RS, CC BY 4.0), uključujući dvojezične talijanske i mađarske nazive. Preuzimanje je veliko oko 45 MB; spremaju se samo središta naselja.",
  "tools.geocode.dguTooltip": "Oko 24.000 hrvatskih naseljenih mjesta iz registra geografskih imena (Državna geodetska uprava) — naselja, sela, zaseoci, gradske četvrti i napuštena naselja, s talijanskim, mađarskim, srpskim i povijesnim nazivima. Preuzimanje je veliko oko 8 MB.",
  "tools.geocode.gursAddressesTooltip": "Svih 580.505 slovenskih adresa iz službenog registra adresa (Geodetska uprava RS, CC BY 4.0, preuzimanje iz katastra nekretnina) — ulica, kućni broj, općina i pošta, svaka s vlastitom koordinatom. Preuzimanje je veliko oko 20 MB i traje nekoliko minuta; nakon toga svaka se slovenska adresa traži ovdje, potpuno bez mreže, a cijelo selo dobiva odgovor odjednom.",
  "tools.geocode.dguAddressesTooltip": "Svih 1,68 milijuna hrvatskih adresa iz registra adresa DGU-a (Državna geodetska uprava, preuzimanje INSPIRE) — ulica, kućni broj i pošta, svaka s vlastitom koordinatom. Preuzimanje je veliko oko 85 MB, priprema traje nekoliko minuta, a u pregledniku zauzima oko 40 MB; nakon toga svaka se hrvatska adresa traži ovdje, potpuno bez mreže.",
  "tools.geocode.downloadNeedsOptIn": "Dopustite mrežne upite u Postavkama → Napredno.",
