  "tools.sources.dupHeading": "Mogući duplikati",
  "tools.sources.dupIntro": "Zapisi koji opisuju isti medij, izvor ili spremište pod različitim oznakama. Zapis koji govori manje od drugog zapisa istog naslova (na primjer matična knjiga bez signature) pridružuje se skupini tog zapisa. Zadržava se zapis s najviše referenci, a ono što navode samo drugi zapisi prenosi se u njega. Odaberite skupine za spajanje i primijenite: svaka se skupina u vašoj datoteci sažima u jedan zapis, a svi se navodi preusmjeravaju na njega, i to u jednom koraku.",
