  "tools.sources.tidyLinksHint": "Poveznice na FamilySearch kod medija iz ovog pokretanja prepisuje u oblik koji datoteka čuva: trag preglednika slika (view, groupId, wc, lang) govori samo kako je čitatelj došao do stranice i otpada, a oznake slike (i) i zbirke (cc), koje kopirana poveznica nema, dopunjuju se iz onoga što je pokretanje saznalo — tako broj stranice ostaje čitljiv bez ponovnog upita web-mjestu.",
  "tools.sources.pasteCitation": "Zalijepite navod i polja će se ispuniti",
  "tools.sources.fsSignin": "stranica za prijavu",
  "tools.sources.fsSigninHint": "Stranice zapisa na FamilySearchu otvaraju se tek nakon prijave, pa ih upit ne može pročitati — kopirajte navod sa stranice i zalijepite ga u uređivač ✎ ili na mjesto ove poveznice stavite poveznicu na sliku, kako bi se podaci ispunili.",
  "tools.sources.heldBack_one": "{{count}} označena stranica imenovana je samo svojom poveznicom.",
  "tools.sources.heldBack_few": "{{count}} označene stranice imenovane su samo svojim poveznicama.",
  "tools.sources.heldBack_other": "{{count}} označenih stranica imenovano je samo svojim poveznicama.",
  "tools.sources.editRecordHint": "Uredite zapis izvora kojem se ova skupina pridružuje — sva njegova polja, uključujući poveznicu.",
  "tools.sources.swapLinkBadge": "nova poveznica",
  "tools.sources.swapLinkHint": "Poveznica iz koje se ispisuje ovaj izvor. Na njezino mjesto stavite drugu — sliku na kojoj se temelji stranica zapisa na FamilySearchu i koju upit može pročitati — i podaci se čitaju s nje. Kad primijenite, medij ovog izvora preusmjerava se na novu poveznicu, i u zapisima koji taj medij navode.",
  "tools.sources.lookupFailed": "Stranica za ovu poveznicu nije dala ništa čime bi se ispunila ova polja — posrednički poslužitelj možda nije dostupan ili se poveznica otvara tek nakon prijave.",
  "tools.sources.regroupHeading": "Spremišta po mjestima",
  "tools.sources.regroupIntro": "FamilySearch objavljuje po zbirkama, a spremište je mjesto gdje se izvornici čuvaju — zato izvori pripadaju pod mjesto odakle su zapisi, a naziv zbirke ostaje naslov samog izvora. To je mjesto država, a kod država koje se objavljuju po saveznim državama, kao što je slučaj s američkim zapisima, savezna država. Odaberite mjesta i primijenite: svaki se izvor povezuje sa spremištem svojeg mjesta, a spremište koje nakon premještanja ostane prazno uklanja se, i to u jednom koraku.",
