  "tools.search.clear": "Očisti filtar",
  "tools.dna.intro": "Alat iz datoteke čita podatke koje o vašem rodoslovnom stablu traže portali za testiranje DNK-a. Prikazuje izravnu očevu (Y-DNK) i majčinu (mtDNK) liniju s najranijim poznatim pretkom u svakoj od njih. Prezimena svih predaka s mjestima priprema kao datoteku CSV za uvoz u FamilyTreeDNA. Uzimaju se u obzir samo biološki roditelji, a posvojitelji i udomitelji ne. Datoteka se pritom ne mijenja.",
  "tools.dna.person": "Testirana osoba",
  "tools.dna.pick": "Odaberite osobu…",
  "tools.dna.personHint": "Osoba za čiji test DNK-a pripremate podatke. Odabir ovdje vrijedi samo za ovaj alat.",
