  "tools.dna.eka": "Najraniji poznati predak",
  "tools.dna.ekaHint": "Najudaljeniji predak u ovoj liniji koji ima zapisano ime i prezime. Predak kojeg poznajemo samo po imenu ne pomaže vašim DNK-podudaranjima pronaći zajedničkog pretka, pa se uzima generacija ispod njega. Ako želite drugog pretka, odaberite ga na popisu u nastavku.",
  "tools.dna.eka.none": "U ovoj liniji nitko nema zapisano ime i prezime.",
