  "tools.publish.intro": "Alat priprema jednu datoteku HTML koju rođaci otvaraju u pregledniku, a vi je možete postaviti i na bilo koji web-poslužitelj. Stranica prikazuje rodoslovno stablo s dijagramima, kartom, statistikom i stranicama osoba, ali sadrži samo podatke za prikaz. Kontaktni podaci i ID-ovi zapisa nikad nisu uključeni, a izvore, adrese, bilješke i fotografije uključujete po želji. Datoteku GEDCOM sa stranice nije moguće preuzeti. Vaša radna datoteka ostaje netaknuta.",
