  "settings.display.dates": "Prikaz datuma",
  "settings.display.dates.hint": "Kako se datumi prikazuju na zaslonu: onako kako ih zapisuje datoteka (ABT 5 MAR 1850), riječima (oko 5. ožujka 1850.) ili u obliku po vašem izboru (ABT 05.03.1850). Datoteka zadržava svoj oblik, a polje za datum tijekom uređivanja pokazuje zapis iz datoteke.",
  "settings.display.dates.file": "Kao u datoteci",
