  "settings.links.title": "Mrežne pretrage",
  "settings.links.fetch": "Potraži podatke na mreži",
  "settings.links.fetch.hint": "Jedan prekidač za sve pretrage koje napuštaju vaš uređaj: naslov stranice izvora kad ga dodate iz golog URL-a, geokodiranje — OpenStreetMap, Genealoški imenik mjesta (GOV) te slovenski registar adresa i geografski imenik GURS — i pretragu osoba u slovenskom i hrvatskom rodoslovnom indeksu (indeks.rodoslovje.si, indeks.rodoslovlje.hr). Zadano isključeno. Preuzimanje cijelog imenika mjesta nije upit — o vašoj datoteci ne otkriva ništa — i ne treba mu prekidač.",
  "settings.links.fetch.relays": "Preko javnog posrednika ide samo pretraga naslova stranice, i to ovim redoslijedom:",
  "settings.links.fetch.relaysNote": "Usluge geokodiranja i rodoslovni indeksi pozivaju se izravno, kao i FamilySearch — njegove poveznice odgovaraju same za sebe pa ih nijedan posrednik ne vidi. Šalje se samo tražena adresa, poveznica ili ime — nikad vaše datoteke.",
  "settings.links.indexContributor": "Vaše stablo u slovenskom indeksu",
  "settings.links.indexContributor.hint": "Ime pod kojim je vaše stablo objavljeno na indeks.rodoslovje.si (više imena odvojite zarezom). Pri pretrazi indeksa vaše se stablo izostavlja, a osobe koje to stablo već sadrži označavaju se.",
  "settings.links.indexContributor.placeholder": "Vaše stablo, npr. Novak",
  "settings.links.indexContributorHr": "Vaše stablo u hrvatskom indeksu",
  "settings.links.indexContributorHr.hint": "Ime pod kojim je vaše stablo objavljeno na indeks.rodoslovlje.hr (više imena odvojite zarezom). Pri pretrazi hrvatskog indeksa vaše se stablo izostavlja, a osobe koje to stablo već sadrži označavaju se.",
  "settings.links.indexContributorHr.placeholder": "Vaše stablo, npr. Horvat",
  "settings.searchSites.title": "Pretraga osoba",
  "settings.searchSites.hint": "Stranice koje ploča Pretraga u prikazu Uređivanje nudi za osobu. Rodoslovni indeksi ispisuju pogotke izravno na ploči ako je uključeno „Potraži podatke na mreži“.",
  "settings.searchSites.needFetch": "Za pretragu rodoslovnih indeksa gore uključite „Potraži podatke na mreži“.",
  "settings.geo.title": "Imenici mjesta",
  "settings.geo.hint": "Geografski imenici s kojima se uspoređuju nazivi mjesta — naselja s koordinatama, spremljena u ovom pregledniku i u upotrebi u svim poljima mjesta, kartama i geokodiranju. Postavite ih jednom; ostaju i nakon zamjene datoteke.",
  "settings.geo.empty": "Imenik još nije uvezen. Bez njega nazive mjesta nema s čim usporediti, pa vam aplikacija ne može predložiti nijednu koordinatu — svaku i dalje možete unijeti ručno.",
